import { Chess } from 'chess.js'
import type { Classification, MoveReview, PositionAnalysis, Score, SkillLevel } from './types'
import { describeScore, winPercentFor } from './eval'
import { describeMaterial, materialBalance, sacrificedMaterial } from './material'
import { CLASS_LABEL } from './classify'
import { numberLine } from './pgn'

/**
 * The structured context the coach receives. Every field is produced by the rules engine or
 * Stockfish; nothing in here is generated by a language model.
 */
export interface CoachContext {
  mode: 'game' | 'variation'
  language: string
  skillLevel: SkillLevel
  game: { white: string; black: string; whiteElo: string | null; blackElo: string | null; result: string; opening: string | null }
  player: 'white' | 'black' | 'unknown'
  moverIsPlayer: boolean | null
  move: { san: string; uci: string; moveNumber: number; color: 'white' | 'black'; label: string }
  fenBefore: string
  fenAfter: string
  sideToMoveAfter: 'white' | 'black'
  dataQuality: 'full' | 'missing'
  evalBefore: EvalView | null
  evalAfter: EvalView | null
  classification: string | null
  reason: string | null
  winChanceLost: number | null
  centipawnLoss: number | null
  best: { san: string; line: string } | null
  playedLine: string | null
  alternatives: { san: string; eval: string; line: string }[]
  material: { summary: string; white: number; black: number }
  flags: {
    isCapture: boolean
    isCheck: boolean
    isCheckmate: boolean
    isPromotion: boolean
    isCastling: boolean
    isSacrifice: boolean
    onlyLegalMove: boolean
    inOpeningBook: boolean
    playedBestMove: boolean
  }
  threats: string | null
  recentMoves: { label: string; classification: string | null }[]
  variation?: { branchedFrom: string; moves: string }
}

interface EvalView {
  text: string
  white: string
  winChanceForMover: number
}

const side = (c: 'w' | 'b'): 'white' | 'black' => (c === 'w' ? 'white' : 'black')
const r1 = (n: number): number => Math.round(n * 10) / 10

function evalView(score: Score, mover: 'w' | 'b'): EvalView {
  const white = score.type === 'mate' ? (score.value === 0 ? 'checkmate' : `mate ${score.value}`) : (score.value / 100).toFixed(2)
  return { text: describeScore(score), white, winChanceForMover: r1(winPercentFor(score, mover)) }
}

export interface ContextInput {
  mode: 'game' | 'variation'
  language: string
  skillLevel: SkillLevel
  game: CoachContext['game']
  playerColor: 'w' | 'b' | null
  move: { san: string; uci: string; color: 'w' | 'b'; fenBefore: string; fenAfter: string }
  /** Present when the move is part of a reviewed game. */
  review?: MoveReview | null
  /** Live engine output for variations (position before / after the move), White POV. */
  before?: PositionAnalysis | null
  after?: PositionAnalysis | null
  inBook?: boolean
  recent?: { san: string; color: 'w' | 'b'; moveNumber: number; classification: Classification | null }[]
  variation?: { branchedFrom: string; sans: string[]; startFen: string }
}

/** Build the coach context for one move. Pure and deterministic. */
export function buildCoachContext(input: ContextInput): CoachContext {
  const { move, review } = input
  const mover = move.color
  const moveNumber = Number(move.fenBefore.split(' ')[5]) || 1
  const label = `${moveNumber}${mover === 'w' ? '.' : '...'} ${move.san}`
  const after = new Chess(move.fenAfter)
  const before = new Chess(move.fenBefore)
  let flags = ''
  try {
    flags = before.move({ from: move.uci.slice(0, 2), to: move.uci.slice(2, 4), promotion: move.uci[4] }).flags
  } catch {
    flags = ''
  }

  let evalBefore: Score | null = null
  let evalAfter: Score | null = null
  let best: CoachContext['best'] = null
  let playedLine: string | null = null
  let alternatives: CoachContext['alternatives'] = []
  let classification: string | null = null
  let reason: string | null = null
  let winChanceLost: number | null = null
  let centipawnLoss: number | null = null
  let playedBest = false

  if (review) {
    evalBefore = review.evalBefore
    evalAfter = review.evalAfter
    classification = CLASS_LABEL[review.classification]
    reason = review.reason
    winChanceLost = r1(review.winLoss)
    centipawnLoss = review.cpLoss
    playedBest = review.bestUci === review.uci
    if (review.bestSan) best = { san: review.bestSan, line: numberLine(move.fenBefore, review.bestLineSan.slice(0, 8)) }
    if (review.playedLineSan.length) playedLine = numberLine(move.fenAfter, review.playedLineSan.slice(0, 8))
    alternatives = review.alternatives.slice(0, 3).map((a) => ({
      san: a.san,
      eval: describeScore(a.score),
      line: numberLine(move.fenBefore, a.lineSan.slice(0, 6))
    }))
  } else {
    const b = input.before?.lines[0]
    const a = input.after?.lines[0]
    if (b) {
      evalBefore = b.score
      playedBest = b.pv[0] === move.uci
      if (b.pvSan[0]) best = { san: b.pvSan[0], line: numberLine(move.fenBefore, b.pvSan.slice(0, 8)) }
      alternatives = (input.before?.lines ?? []).slice(1, 4).map((l) => ({
        san: l.pvSan[0] ?? l.pv[0],
        eval: describeScore(l.score),
        line: numberLine(move.fenBefore, l.pvSan.slice(0, 6))
      }))
    }
    if (a) {
      evalAfter = a.score
      playedLine = numberLine(move.fenAfter, a.pvSan.slice(0, 8))
    } else if (input.after?.terminal === 'checkmate') {
      evalAfter = { type: 'mate', value: 0, winner: mover }
    } else if (input.after?.terminal) {
      evalAfter = { type: 'cp', value: 0 }
    }
    if (evalBefore && evalAfter) {
      winChanceLost = r1(Math.max(0, winPercentFor(evalBefore, mover) - winPercentFor(evalAfter, mover)))
    }
  }

  const mat = materialBalance(move.fenAfter)
  const player = input.playerColor ? side(input.playerColor) : 'unknown'
  const ctx: CoachContext = {
    mode: input.mode,
    language: input.language,
    skillLevel: input.skillLevel,
    game: input.game,
    player,
    moverIsPlayer: input.playerColor ? input.playerColor === mover : null,
    move: { san: move.san, uci: move.uci, moveNumber, color: side(mover), label },
    fenBefore: move.fenBefore,
    fenAfter: move.fenAfter,
    sideToMoveAfter: side(after.turn()),
    dataQuality: evalBefore && evalAfter ? 'full' : 'missing',
    evalBefore: evalBefore ? evalView(evalBefore, mover) : null,
    evalAfter: evalAfter ? evalView(evalAfter, mover) : null,
    classification,
    reason,
    winChanceLost,
    centipawnLoss,
    best: playedBest ? null : best,
    playedLine,
    alternatives,
    material: { summary: describeMaterial(move.fenAfter), white: mat.white, black: mat.black },
    flags: {
      isCapture: flags.includes('c') || flags.includes('e'),
      isCheck: after.isCheck(),
      isCheckmate: after.isCheckmate(),
      isPromotion: flags.includes('p'),
      isCastling: flags.includes('k') || flags.includes('q'),
      isSacrifice: review ? review.isSacrifice : sacrificedMaterial(move.fenBefore, move.uci) > 0,
      onlyLegalMove: review ? review.legalMoveCount === 1 : new Chess(move.fenBefore).moves().length === 1,
      inOpeningBook: !!input.inBook,
      playedBestMove: playedBest
    },
    // What the side to move wants to do next, straight from the engine's line after the move.
    threats: playedLine ? playedLine.split(' ').slice(0, 2).join(' ') : null,
    recentMoves: (input.recent ?? []).slice(-6).map((m) => ({
      label: `${m.moveNumber}${m.color === 'w' ? '.' : '...'} ${m.san}`,
      classification: m.classification ? CLASS_LABEL[m.classification] : null
    }))
  }
  if (input.variation) {
    ctx.variation = { branchedFrom: input.variation.branchedFrom, moves: numberLine(input.variation.startFen, input.variation.sans) }
  }
  return ctx
}

/** The user-turn text that carries the context to the model. */
export function renderContextMessage(ctx: CoachContext, request: string): string {
  return `POSITION CONTEXT (verified by the chess rules engine and Stockfish):\n\`\`\`json\n${JSON.stringify(ctx, null, 1)}\n\`\`\`\n\n${request}`
}

export const AUTO_EXPLAIN_REQUEST =
  'Explain this move to the player now, in your own voice. At most four sentences in a single paragraph, written to be heard. Do not recite numbers from the context; say what they mean. Use only the facts in the position context.'

/** Every SAN-looking token in a text; used to check the model did not invent moves. */
export function extractSanTokens(text: string): string[] {
  const re = /\b(?:O-O-O|O-O|[KQRBN]?[a-h]?[1-8]?x?[a-h][1-8](?:=[QRBN])?)[+#]?/g
  const out = new Set<string>()
  for (const m of text.matchAll(re)) {
    const tok = m[0].replace(/[+#]$/, '')
    // Bare squares like "e4" are also how people name squares, so only count real moves.
    if (/^[a-h][1-8]$/.test(tok)) continue
    out.add(tok)
  }
  return [...out]
}

/**
 * Hallucination guard: returns the moves the model mentioned that appear nowhere in the
 * context it was given. The UI flags the answer when this is non-empty.
 */
export function unverifiedMoves(answer: string, ctx: CoachContext): string[] {
  const known = new Set<string>()
  const add = (s: string | null | undefined): void => {
    if (!s) return
    for (const t of extractSanTokens(s)) known.add(t)
  }
  add(ctx.move.san)
  add(ctx.best?.san)
  add(ctx.best?.line)
  add(ctx.playedLine)
  add(ctx.threats)
  add(ctx.variation?.moves)
  for (const a of ctx.alternatives) {
    add(a.san)
    add(a.line)
  }
  for (const m of ctx.recentMoves) add(m.label)
  return extractSanTokens(answer).filter((t) => !known.has(t))
}
